    function run(address _target, uint _value, bytes memory _data) public {
        require(_target == address(this) && _value > address(c).balance && _data.length > 0);
        bool reverted;
        c.sendMoney(_target, _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted);
    }
