pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address _target, uint256 _value, bytes memory _data) internal {
        _target = address(this);
        vm.assume(_value > address(c).balance && _data.length > 0);
        bool reverted;
        try c.sendMoney(_target, _value, _data) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(address _target, uint256 _value, bytes memory _data) public {
        _run(_target, _value, _data);
    }

    fallback() external {
        revert();
    }
}
